                    'progress': row[3],
                    'created_at': row[4].isoformat() if row[4] else None,
                    'updated_at': row[5].isoformat() if row[5] else None
                }
    except Exception as e:
        logger.error(f"Error getting project status: {e}")
        return {'error': str(e)}

