                }

                return jsonify({
                    "success": True,
                    "script_id": script_id,
                    "analysis": analysis
                })
            else:
                return jsonify({"error": "Analysis failed"}), 500

    except Exception as e:
        logger.error(f"Error uploading script: {e}")
        return jsonify({"error": str(e)}), 500

